package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
)

var (
	tempDir    = "/var/lib/converter/workspace"
	sessionMu  sync.Mutex
	sessions   = make(map[string]string)
)

func generateToken() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	file, header, err := r.FormFile("document")
	if err != nil {
		http.Error(w, "Missing file", 400)
		return
	}
	defer file.Close()

	// Validate extension
	ext := strings.ToLower(filepath.Ext(header.Filename))
	if ext != ".docx" && ext != ".odt" && ext != ".rtf" {
		http.Error(w, "Unsupported format", 400)
		return
	}

	token := generateToken()
	workspace := filepath.Join(tempDir, token)
	os.MkdirAll(workspace, 0750)

	// Save uploaded file - filename is user-controlled
	dstPath := filepath.Join(workspace, header.Filename)
	dst, err := os.Create(dstPath)
	if err != nil {
		http.Error(w, "Internal error", 500)
		return
	}
	io.Copy(dst, file)
	dst.Close()

	sessionMu.Lock()
	sessions[token] = dstPath
	sessionMu.Unlock()

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"token":"%s"}`, token)
}

func convertHandler(w http.ResponseWriter, r *http.Request) {
	token := r.URL.Query().Get("token")
	format := r.URL.Query().Get("format")

	if token == "" || format == "" {
		http.Error(w, "Missing parameters", 400)
		return
	}

	sessionMu.Lock()
	srcPath, ok := sessions[token]
	sessionMu.Unlock()

	if !ok {
		http.Error(w, "Invalid token", 404)
		return
	}

	// format parameter is injected directly into shell command
	outputDir := filepath.Dir(srcPath)
	cmdStr := fmt.Sprintf("libreoffice --headless --convert-to %s --outdir %s %s",
		format, outputDir, srcPath)

	cmd := exec.Command("bash", "-c", cmdStr)
	cmd.Env = append(os.Environ(), "HOME=/tmp")
	output, err := cmd.CombinedOutput()
	if err != nil {
		http.Error(w, fmt.Sprintf("Conversion failed: %s", string(output)), 500)
		return
	}

	// Find output file
	baseName := strings.TrimSuffix(filepath.Base(srcPath), filepath.Ext(srcPath))
	outFile := filepath.Join(outputDir, baseName+"."+strings.Split(format, " ")[0])

	w.Header().Set("Content-Disposition", "attachment; filename="+filepath.Base(outFile))
	http.ServeFile(w, r, outFile)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("OK"))
}

func main() {
	os.MkdirAll(tempDir, 0750)
	http.HandleFunc("/upload", uploadHandler)
	http.HandleFunc("/convert", convertHandler)
	http.HandleFunc("/health", healthHandler)
	fmt.Println("Document converter listening on :8080")
	http.ListenAndServe(":8080", nil)
}
